1	package net.officefloor.hq.app.period;
2	
3	import java.math.BigDecimal;
4	import java.time.LocalDate;
5	import java.util.HashMap;
6	import java.util.List;
7	import java.util.Map;
8	import java.util.function.Function;
9	import java.util.stream.Collectors;
10	import net.officefloor.hq.app.Audit;
11	import net.officefloor.hq.app.claim.Claim;
12	import net.officefloor.hq.app.claim.ClaimLog;
13	import net.officefloor.hq.app.claim.ClaimLogRepository;
14	import net.officefloor.hq.app.claim.ClaimRepository;
15	import net.officefloor.hq.app.claim.ClaimStatus;
16	import net.officefloor.hq.app.person.Person;
17	import net.officefloor.hq.app.person.PersonRepository;
18	import net.officefloor.hq.app.rollup.RollupService;
19	import net.officefloor.hq.app.settings.Action;
20	import net.officefloor.hq.app.settings.SettingsService;
21	import net.officefloor.hq.app.sheet.Sheet;
22	import net.officefloor.hq.app.sheet.SheetNotFoundException;
23	import net.officefloor.hq.app.sheet.SheetRepository;
24	import org.springframework.stereotype.Service;
25	import org.springframework.transaction.annotation.Transactional;
26	
27	/** The periods of each sheet: uniquely named, none overlapping another. A period can be closed, which
28	 * fixes its due-total then, and a steward (or the roles the permission matrix allows) can reopen it, which makes its due-total live again. */
29	@Service
30	public class PeriodService {
31	
32	    private final PeriodRepository periods;
33	    private final SheetRepository sheets;
34	    private final ClaimRepository claims;
35	    private final ClaimLogRepository logs;
36	    private final PersonRepository people;
37	    private final RollupService rollup;
38	    private final SettingsService settings;
39	    private final Audit audit;
40	
41	    public PeriodService(PeriodRepository periods, SheetRepository sheets, ClaimRepository claims,
42	            ClaimLogRepository logs, PersonRepository people, RollupService rollup, SettingsService settings, Audit audit) {
43	        this.periods = periods;
44	        this.sheets = sheets;
45	        this.claims = claims;
46	        this.logs = logs;
47	        this.people = people;
48	        this.rollup = rollup;
49	        this.settings = settings;
50	        this.audit = audit;
51	    }
52	
53	    /** The sheet's periods, by from-date. */
54	    @Transactional(readOnly = true)
55	    public List<Period> list(String sheetId) {
56	        return periods.findBySheetIdOrderByFromAsc(sheetId);
57	    }
58	
59	    @Transactional
60	    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to) {
61	        if (!sheets.existsById(sheetId)) {
62	            throw new SheetNotFoundException();
63	        }
64	        if (to.isBefore(from)) {
65	            throw new PeriodRefusedException("to before from");
66	        }
67	        if (periods.findBySheetIdAndNameKey(sheetId, Period.keyOf(name)).isPresent()) {
68	            throw new PeriodRefusedException("name taken");
69	        }
70	        if (periods.findBySheetIdOrderByFromAsc(sheetId).stream().anyMatch(p -> p.overlaps(from, to))) {
71	            throw new PeriodRefusedException("overlaps");
72	        }
73	        Period period = periods.saveAndFlush(new Period(sheetId, name, from, to));
74	        audit.change("PERIOD_ADDED", sheetId, user, "period=" + period.getName(), "from=" + period.getFrom(),
75	                "to=" + period.getTo());
76	        return period;
77	    }
78	
79	    /** Close the period, fixing its due-total now; refused when the user's role may not close (see
80	     * {@link SettingsService#allowed}) or it is already closed. */
81	    @Transactional
82	    public Period close(String sheetId, String user, long periodId) {
83	        Period period = periods.lockByIdAndSheetId(periodId, sheetId).orElseThrow(PeriodNotFoundException::new);
84	        if (!settings.allowed(sheetId, user, Action.CLOSE)) {
85	            throw new PeriodNotStewardException();
86	        }
87	        if (period.isClosed()) {
88	            throw new PeriodRefusedException("already closed");
89	        }
90	        period.close(personTotalsOf(period));
91	        periods.flush();
92	        audit.change("PERIOD_CLOSED", sheetId, user, "period=" + period.getName(),
93	                "total=" + period.getClosedTotal().toPlainString());
94	        return period;
95	    }
96	
97	    /** Reopen the period, making its due-total live again; refused when the user's role may not
98	     * reopen (a steward's by default, see {@link SettingsService#allowed}) or the period is not closed. */
99	    @Transactional
100	    public Period reopen(String sheetId, String user, long periodId) {
101	        Period period = periods.lockByIdAndSheetId(periodId, sheetId).orElseThrow(PeriodNotFoundException::new);
102	        if (!settings.allowed(sheetId, user, Action.REOPEN)) {
103	            throw new PeriodNotStewardException();
104	        }
105	        if (!period.isClosed()) {
106	            throw new PeriodRefusedException("not closed");
107	        }
108	        period.reopen();
109	        periods.flush();
110	        audit.change("PERIOD_REOPENED", sheetId, user, "period=" + period.getName());
111	        return period;
112	    }
113	
114	    /** Each person's due-total for the period now, by person id, for everyone on the sheet: the sum of
115	     * what is due on their claims dated in it that counted by the status each had at the end of the
116	     * period's last day (see {@link #statusAt}), as each shows it now, late charges included (a
117	     * claim with no figure adds nothing, nor does an OPEN claim deferred on the sheet's today or an unbound OPEN claim dated within one of its person's holds, while the claim is still OPEN or PENDING now). */
118	    private Map<Long, BigDecimal> personTotalsOf(Period period) {
119	        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(period.getSheetId()).stream()
120	                .collect(Collectors.toMap(Person::getId, Function.identity()));
121	        Map<Long, BigDecimal> totals = new HashMap<>();
122	        for (Long id : byId.keySet()) totals.put(id, BigDecimal.ZERO.setScale(2));
123	        LocalDate today = sheets.findById(period.getSheetId()).map(Sheet::getToday).orElse(null);
124	        List<Claim> dated = claims.findBySheetIdOrderByListedDescIdDesc(period.getSheetId()).stream()
125	                .filter(claim -> period.overlaps(claim.getDate(), claim.getDate())).toList();
126	        Map<Long, List<ClaimLog>> logsOf = dated.isEmpty() ? Map.of()
127	                : logs.findByClaimIdInOrderByIdAsc(dated.stream().map(Claim::getId).toList()).stream()
128	                        .collect(Collectors.groupingBy(ClaimLog::getClaimId));
129	        for (Claim claim : dated) {
130	            Person person = byId.get(claim.getPersonId());
131	            ClaimStatus status = statusAt(logsOf.getOrDefault(claim.getId(), List.of()), period.getTo());
132	            if (person == null || status == null) continue;
133	            boolean counts = claim.getStatus().isOpen() ? RollupService.countsAs(claim, status, person, today) : status.counts();
134	            if (!counts) continue;
135	            BigDecimal figure = rollup.shownOf(claim, person);
136	            if (figure != null) totals.merge(person.getId(), figure, BigDecimal::add);
137	        }
138	        return totals;
139	    }
140	
141	    /** The status a claim had at the end of {@code day}, by its status log, oldest first, whose lines
142	     * are dated with the sheet's today when each change was made; null when it was added after. */
143	    private static ClaimStatus statusAt(List<ClaimLog> log, LocalDate day) {
144	        ClaimStatus status = null;
145	        for (ClaimLog line : log) {
146	            if (line.getDate().isAfter(day)) break;
147	            status = line.getStatus();
148	        }
149	        return status;
150	    }
151	}
