    const limitFrom = this.limitFrom().trim();
    const floorFrom = this.floorFrom().trim();
    const capFrom = this.capFrom().trim();
    const proofThresholdFrom = this.proofThresholdFrom().trim();
    const termsFrom = this.termsFrom().trim();
